const body = $input.first().json;
const alerts = body.alerts || [];
const alert = alerts[0] || {};
const desc = (alert.annotations && (alert.annotations.description || alert.annotations.__value_string__) || '');

function parseFields(line) {
  var fields = {};
  var regex = /(\w+)=([^\s]+)/g;
  var m;
  while ((m = regex.exec(line)) !== null) {
    fields[m[1]] = m[2];
  }
  return fields;
}

var fields = parseFields(desc);

return [{
  json: {
    eventType: fields.eventType || 'UNKNOWN',
    targetId: fields.targetId || '',
    exceptionType: fields.exceptionType || '',
    reason: fields.reason || desc,
    alertTime: alert.startsAt || new Date().toISOString(),
    rawLog: desc
  }
}];

const parsed = $('Parse EMBEDDING_FAIL Log').first().json;
const reindexResp = $json;

return [{
  json: {
    slackPayload: {
      text: '🔄 *[EMBEDDING_FAIL] 자동 재인덱싱 트리거*',
      attachments: [{
        color: 'good',
        fields: [
          { title: '타입', value: parsed.eventType || '-', short: true },
          { title: '대상 ID', value: parsed.targetId || '-', short: true },
          { title: '예외', value: parsed.exceptionType || '-', short: true },
          { title: '조치', value: '자동 reindex API 호출 완료', short: true },
          { title: '사유', value: parsed.reason || '-', short: false }
        ],
        footer: 'POCAT Monitoring | ' + parsed.alertTime
      }]
    }
  }
}];

const parsed = $('Parse EMBEDDING_FAIL Log').first().json;

return [{
  json: {
    ...parsed,
    geminiRequest: {
      model: 'gemini-2.0-flash',
      max_tokens: 250,
      messages: [
        {
          role: 'system',
          content: 'POCAT 임베딩 실패 분석 AI입니다. 한국어로 3줄 이내 답변하세요.'
        },
        {
          role: 'user',
          content: '임베딩 반복 실패 감지\n타입: ' + parsed.eventType + '\n대상 ID: ' + parsed.targetId + '\n예외: ' + parsed.exceptionType + '\n사유: ' + parsed.reason + '\n\n원인 분류(벡터DB장애/API한도초과/데이터이상/인프라문제)와 조치 방법을 답변하세요.'
        }
      ]
    }
  }
}];

const geminiResp = $json;
const analysis = (geminiResp.choices && geminiResp.choices[0] && geminiResp.choices[0].message && geminiResp.choices[0].message.content) || '분석 실패';
const parsed = $('Parse EMBEDDING_FAIL Log').first().json;

return [{
  json: {
    slackPayload: {
      text: '❌ *[EMBEDDING_FAIL] 임베딩 지속 실패 — 수동 확인 필요*',
      attachments: [{
        color: 'danger',
        fields: [
          { title: '타입', value: parsed.eventType || '-', short: true },
          { title: '대상 ID', value: parsed.targetId || '-', short: true },
          { title: '예외', value: parsed.exceptionType || '-', short: true },
          { title: '사유', value: parsed.reason || '-', short: true },
          { title: 'AI 분석', value: analysis, short: false }
        ],
        footer: 'POCAT Monitoring | ' + parsed.alertTime
      }]
    }
  }
}];
